{"command": "python3 - <<'PY'
import workcell, time, json

def move(x,y,z):
    r=workcell.call('arm','move',str(x),str(y),str(z))
    print('move', x,y,z, r.ok, r.data)
    return r

def probe(x,y, start=130.0, zmin=100.0, threshold=0.6, max_steps=60):
    move(x,y,start)
    # optional tare not each time
    for i in range(max_steps):
        r=workcell.call('arm','step','-0.5')
        if not r.ok:
            print('step err', r.text)
            return None
        d=r.data
        z=d.get('z_mm'); fz=d.get('fz_N',0)
        if fz > threshold:
            # move back up safe
            move(x,y,150)
            return {'x':x,'y':y,'z_contact':z,'fz':fz}
        if z is not None and z < zmin:
            move(x,y,150)
            return {'x':x,'y':y,'z_contact':None,'fz':fz,'z':z}
    move(x,y,150)
    return {'x':x,'y':y,'z_contact':None,'fz':None}

points=[]
# first known center
res=probe(520,-40)
print(res)
points.append(res)
json.dump(points, open('/home/robot/probe_map.json','w'), indent=2)
PY"}

